import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.BZzouRtU.js";const u=JSON.parse('{"title":"ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較","description":"","frontmatter":{"title":"ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較","study":{"source":"C++ Wiki","status":"published","summary":"C++のRAIIと.NET・UnityのGCを、確保、破棄、回収、再利用、OSへの返却と計測の違いから比較する。","section":"reference","format":"article","domain":"runtime"}},"headers":[],"relativePath":"runtime/memory/gc-and-csharp-comparison.md","filePath":"runtime/memory/gc-and-csharp-comparison.md"}'),n={name:"runtime/memory/gc-and-csharp-comparison.md"};function i(l,t,d,s,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ガベージコレクションとの違い-—-c-の管理ヒープ・unityのgc-allocとの比較" tabindex="-1">ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較 <a class="header-anchor" href="#ガベージコレクションとの違い-—-c-の管理ヒープ・unityのgc-allocとの比較" aria-label="Permalink to &quot;ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p><strong>GCは到達できなくなった管理オブジェクトの記憶域を回収し、RAIIはオブジェクトの破棄へ資源の後片付けを結び付けます。</strong> 比べるときは、確保、初期化、破棄、領域の再利用、OSへの返却を別の段階として見ます。</p><p>言語名だけで「C#のnewは速い」「C++のnewは遅い」と決めることはできません。サイズ、初期化、確保頻度、生存期間、ランタイム、回収や補充が必要かによって経路が変わります。<a href="/study/runtime/memory/allocation-journey.html">malloc/newの内部</a>と<a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域・寿命</a>へつながる比較です。</p><h2 id="c-の管理ヒープの仕組み-概要" tabindex="-1">C#の管理ヒープの仕組み(概要) <a class="header-anchor" href="#c-の管理ヒープの仕組み-概要" aria-label="Permalink to &quot;C#の管理ヒープの仕組み(概要)&quot;">​</a></h2><p>まず、Microsoftの<a href="https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/fundamentals" target="_blank" rel="noreferrer">.NET GCの説明</a>を前提にします。以下を、すべてのC#実行環境で固定された実装と考えないでください。</p><ol><li>アプリケーションが管理オブジェクトを作ると、ランタイムが管理ヒープ内の領域を用意し、必要な初期化を行う。</li><li>既に用意した領域に空きがあれば、ポインタを進める方式で確保できる場合がある。空き不足や大きな確保では、領域の取得やGCなど別の処理が関係する。</li><li>GCはスタック上の生存情報、静的な参照、ハンドルなどのルートから到達可能性を調べる。到達できない循環参照も回収対象にできる。</li><li>世代別GCは生存期間の傾向を使って、回収の対象世代を選ぶ。回収のタイミングと停止時間は確保量だけでは決まらない。</li></ol><p>圧縮を行う回収では生存オブジェクトが移動する場合があります。ただし、大きなオブジェクトやpinningなども関係するため、<strong>GCがあれば断片化ゼロとは言えません。</strong> オブジェクトが回収された量、GCが保持する領域、プロセスの常駐量も一致するとは限りません。</p><p>Unity 6.0のMono/IL2CPPは別に確認します。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/analysis/performance-memory/managed-memory/incremental-garbage-collection" target="_blank" rel="noreferrer">GCのモード</a>ではBoehm-Demers-Weiser方式と、複数フレームへ処理を分けるインクリメンタルGCを説明しています。これは1回の停止を分割する方針で、GCの総仕事量をなくす機能ではありません。.NETのGen0/1/2や圧縮の挙動を、そのまま当てはめません。Webなど、対応する動作にも差があります。</p><h2 id="コスト構造の対比" tabindex="-1">コスト構造の対比 <a class="header-anchor" href="#コスト構造の対比" aria-label="Permalink to &quot;コスト構造の対比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>観点</th><th>C++の典型的なRAII設計</th><th>C#/.NETの管理オブジェクト</th></tr></thead><tbody><tr><td>確保</td><td>汎用アロケータや用途別アロケータから取得。再利用で済む場合と補充が必要な場合がある</td><td>管理ヒープから取得。既存領域で済む場合と、回収・拡張が関係する場合がある</td></tr><tr><td>破棄・後片付け</td><td>所有者の破棄などに結び付ける。デストラクタ内の処理にもコストがある</td><td>メモリ回収の時期はGCが管理。ファイル等の後片付けにはDispose/usingなどを使う</td></tr><tr><td>保持される領域</td><td>free/delete後もアロケータが再利用用に保持することがある</td><td>回収後もランタイムが管理ヒープの領域を保持することがある</td></tr><tr><td>停止や遅延</td><td>確保、ロック、ページフォルト、大量破棄などを調べる</td><td>確保、初期化、GCの停止や並行処理の負荷などを調べる</td></tr><tr><td>参照と所有</td><td>生ポインタ・参照は通常非所有。unique_ptr等で所有を表せる</td><td>GCが見る強い参照と到達可能性が管理オブジェクトの生存に関係する</td></tr><tr><td>循環</td><td>shared_ptrだけの強い循環では参照カウントが0にならない</td><td>ルートから到達できない循環は回収対象にできる</td></tr></tbody></table><p>どちらも「いつ使わなくなったか」と「誰がその資源を手放すか」を設計します。GCがあっても、イベント購読やstaticなコレクションが不要なオブジェクトを到達可能に保てば、意図せず記憶域を保持します。<a href="https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/implementing-dispose" target="_blank" rel="noreferrer">Disposeによる資源解放</a>はGCの回収とは区別します。</p><h2 id="unityのgc-alloc対策をc-の語彙で読み直す" tabindex="-1">UnityのGC Alloc対策をC++の語彙で読み直す <a class="header-anchor" href="#unityのgc-alloc対策をc-の語彙で読み直す" aria-label="Permalink to &quot;UnityのGC Alloc対策をC++の語彙で読み直す&quot;">​</a></h2><table tabindex="0"><thead><tr><th>対策</th><th>共通する考え方と注意</th></tr></thead><tbody><tr><td>Listやバッファの再利用</td><td>容量を保持して使い直す。要素数が容量を超える拡張では追加確保が起こり得る</td></tr><tr><td>Object Pool</td><td>同じインスタンスを再利用する。返却時の状態リセット、参照切断、保持容量も設計する</td></tr><tr><td>structの利用</td><td>値型の表現を選ぶ。structにしただけで、常にスタック配置や追加確保ゼロになるわけではない</td></tr><tr><td>文字列・クロージャ等の見直し</td><td>APIと変換のどこで領域が必要になるかを確認する。C++のラムダも格納先やstd::functionへの変換等で確保が関係し得る</td></tr><tr><td>NativeArrayなどの利用</td><td>GCが回収する管理領域と、明示的な解放が必要なネイティブ領域を分ける</td></tr></tbody></table><p>UnityのGC.Allocは、管理領域への確保を追うための指標で、OSから取得した量やGCが回収した量ではありません。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/analysis/performance-memory/managed-memory/introduction" target="_blank" rel="noreferrer">Unity 6.0の管理メモリの説明</a>は、確保の記録、断片化、ヒープ拡張、ネイティブメモリとの違いを説明しています。GC Allocが減っても、保持したプールが大きくなれば総使用量が減るとは限りません。</p><h2 id="c-にgcを入れる選択肢は" tabindex="-1">C++にGCを入れる選択肢は? <a class="header-anchor" href="#c-にgcを入れる選択肢は" aria-label="Permalink to &quot;C++にGCを入れる選択肢は?&quot;">​</a></h2><p>C++で書かれたシステムが、特定のオブジェクト群へGCを使うことはあります。たとえば<a href="/study/game/unreal/gc-and-object-pointers.html">UnrealのUObject</a>と、通常のC++オブジェクトの所有関係は分けて読みます。言語、エンジンの管理方式、個々の資源の寿命は同じ分類ではありません。</p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li><strong>変数のスコープが残れば必ず生存するわけではない。</strong> GCは実行時の生存情報を使います。ネイティブ連携では<a href="https://learn.microsoft.com/en-us/dotnet/api/system.gc.keepalive" target="_blank" rel="noreferrer">GC.KeepAlive</a>等が必要な場合があり、unsafeやネイティブ領域を安全な管理参照と同じ扱いにはできません。</li><li><strong>struct＝スタックではない。</strong> 値型は配列要素やフィールドにもなり、boxingもあります。<a href="https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/builtin-types/value-types" target="_blank" rel="noreferrer">C#値型</a>の値と参照の違いから考えます。</li><li><strong>DestroyとGCは別の寿命を扱う。</strong> UnityのC#ラッパーが残ることと、ネイティブ側の実体が生きていることを同一視しません。</li><li><strong>GC停止時間と確保時間を分けて測る。</strong> 計測対象、フレーム時間、対象端末、確保サイズ、生存期間をそろえない比較から、言語全体の速さは判断できません。</li></ol><h2 id="使い分けの視点-まとめ" tabindex="-1">使い分けの視点(まとめ) <a class="header-anchor" href="#使い分けの視点-まとめ" aria-label="Permalink to &quot;使い分けの視点(まとめ)&quot;">​</a></h2><p>まず必要な寿命、保持してよい最大量、フレーム時間の要件を決めます。そのうえで、管理オブジェクトの再利用、RAII、プール、アリーナ等の候補を計測して選びます。小さな一時確保を減らすことと、シーン全体のメモリを解放することでは、見るべき所有者や指標も異なります。</p><p>OS側の違いを自分で観察する場合は<a href="/study/practice/memory/windows-memory-observation.html">Windows/C++の予約・コミット・書込みのサンプル</a>へ進んでください。このサンプルはGCの停止時間を測るものではありません。</p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>GCがオブジェクトを回収しても、常駐量が同じだけ減るとは言えないのはなぜですか。</li><li>Listの再利用、structへの変更、ネイティブ領域への移動で、それぞれ何を確認しますか。</li><li>GC、Dispose、UnityのDestroyが扱う対象を区別できますか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>自分のプロジェクトの確保を1か所選び、確保量・保持量・回収や破棄の時間を分けて記録します。Unityでは対象バージョンとPlayer/Editor、バックエンド、対象端末、GCモードも記録してください。今回の修正は2026-11-02の一次資料照合であり、これら全環境の性能比較を実行した記録ではありません。</p><p>関連項目：<a href="/study/runtime/memory/allocators-and-pools.html">アロケータの選び方</a> / <a href="/study/runtime/memory/">学習ガイド</a> / <a href="/study/runtime/memory/ownership-and-borrowing.html">所有権と借用</a></p>',27)])])}const p=e(n,[["render",i]]);export{u as __pageData,p as default};
